import { createRequire } from "node:module";
const require = createRequire("<home>

playwright");

const BASE = "http://localhost:4173";
const items = ["Whole milk 2 L", "Smooth peanut butter 340 g", "Oat granola 500 g", "Orange juice 1 L", "Free range eggs, 6"];

const browser = await chromium.launch();
const context = await browser.newContext({ baseURL: BASE });
const page = await context.newPage();
await context.request.post("/__test/reset");
await page.goto("/signin");
await page.getByLabel("Email").fill("ana@pantryrun.test");
await page.getByLabel("Password").fill("pantry");
await page.getByRole("button", { name: "Sign in" }).click();
await page.getByText("Signed in as Ana Torres").waitFor();

for (const name of items) {
  await page.goto("/");
  await page.getByRole("article", { name, exact: true }).getByRole("button", { name: "Add" }).click();
  console.log("status:", await page.getByRole("status").innerText());
}
await page.goto("/");
await page.getByRole("article", { name: "Ground coffee 227 g", exact: true }).getByRole("button", { name: "Add" }).click();

await page.goto("/basket");
for (const name of items) {
  console.log(`basket default, ${name}: checked=${await page.getByLabel(`Allow substitutes for ${name}`).isChecked()}`);
}
// Tick each switch by hand. Each change submits the form and redraws the basket.
for (const name of items) {
  const box = page.getByLabel(`Allow substitutes for ${name}`);
  await Promise.all([page.waitForURL(/\/basket/), page.waitForEvent("load"), box.check()]);
  console.log(`after tick, ${name}: checked=${await page.getByLabel(`Allow substitutes for ${name}`).isChecked()}`);
}
await page.reload();
for (const name of items) {
  console.log(`after reload, ${name}: checked=${await page.getByLabel(`Allow substitutes for ${name}`).isChecked()}`);
}

await page.getByLabel("Quantity of Ground coffee 227 g").fill("6");
await page.getByRole("button", { name: "Update Ground coffee 227 g" }).click();
await page.goto("/slots");
await page.getByRole("button", { name: "Choose a delivery time" }).click();
await page.getByRole("radio", { name: /Mar 12 09:00 to 10:00/ }).check();
await page.getByRole("button", { name: "Reserve" }).click();
await page.waitForURL(/\/basket/);
await page.getByRole("button", { name: "Checkout" }).click();
await page.waitForURL(/\/orders\//);
console.log("order url:", page.url());
for (const row of await page.getByTestId("order-line").all()) {
  console.log("order line:", (await row.innerText()).replace(/\s+/g, " "));
}
await browser.close();

